#include <SoftwareSerial.h>
#include <TinyGPS++.h>
// Library Manager: search "TinyGPS++" by Mikal Hart

// Neo-6M: TX → Arduino pin 4, RX → Arduino pin 3
SoftwareSerial gpsSerial(4, 3);  // (RX, TX)
TinyGPSPlus gps;

void setup() {
  Serial.begin(115200);
  gpsSerial.begin(9600);  // Neo-6M default baud
  Serial.println(F("GPS ready — waiting for fix..."));
}

void loop() {
  // Feed all available GPS bytes to the parser
  while (gpsSerial.available()) {
    gps.encode(gpsSerial.read());
  }

  // Print position when it updates
  if (gps.location.isUpdated()) {
    Serial.print(F("Lat: "));  Serial.print(gps.location.lat(), 6);
    Serial.print(F(" Lng: ")); Serial.print(gps.location.lng(), 6);
    Serial.print(F(" Alt: ")); Serial.print(gps.altitude.meters(), 1); Serial.print(F("m"));
    Serial.print(F(" Sats: ")); Serial.print(gps.satellites.value());
    Serial.print(F(" Speed: ")); Serial.print(gps.speed.kmph(), 1); Serial.println(F(" km/h"));
  }

  // Check if data is arriving
  if (millis() > 10000 && gps.charsProcessed() < 10) {
    Serial.println(F("Error: no GPS data! Check wiring."));
  }
}

// Arduino SENDER: transmits sensor data every 500ms
// Wiring: Sender TX (pin 1) → Receiver RX (pin 0)
// IMPORTANT: disconnect TX pin when uploading new firmware!

void setup() {
  Serial.begin(9600);
}

void loop() {
  int sensorVal = analogRead(A0);
  float voltage = sensorVal * 5.0 / 1023.0;

  // Send as: VAL:value\n
  Serial.print(F("VAL:"));
  Serial.println(voltage, 2);
  delay(500);
}

// Arduino RECEIVER: reads sensor data from sender
#include <SoftwareSerial.h>
SoftwareSerial senderSerial(10, 11);  // RX=10 (← sender TX), TX=11

void setup() {
  Serial.begin(115200);    // USB debug
  senderSerial.begin(9600); // must match sender
}

void loop() {
  if (senderSerial.available()) {
    String line = senderSerial.readStringUntil('\n');
    line.trim();
    if (line.startsWith("VAL:")) {
      float voltage = line.substring(4).toFloat();
      Serial.print(F("Received voltage: "));
      Serial.println(voltage, 2);
    }
  }
}
